type Person={id?:string;name:string;initials:string;email:string;phone:string;status:string;group:string;since:string;birthDate?:string;gender?:string;maritalStatus?:string;cpf?:string;campus?:string;campusId?:string;firstVisit?:string;joined?:string;baptized?:string;baptismDate?:string;tags?:string;access?:string;address?:string;number?:string;extra?:string;district?:string;city?:string;state?:string;zip?:string;emergencyName?:string;emergencyPhone?:string;notes?:string;privacy?:boolean;imageConsent?:boolean;messages?:boolean};
type ChurchUnit={id:string;registration_code?:number;parent_unit_id?:string;name:string;type:string;pastor_name?:string;city?:string;state?:string;financial_autonomy:number;communication_autonomy:number;branding_autonomy:number;access_role?:string;include_children?:number};
const nav=[['⌂','Visão geral'],['♙','Pessoas'],['⌁','Famílias e termos'],['▣','Aplicativo do membro'],['★','Área Kids'],['⌂','Igrejas e unidades'],['♜','Usuários e permissões'],['◈','Cultos e eventos'],['⌾','Células'],['✓','Escalas'],['♫','Louvor'],['◌','Comunicação'],['↗','Transmissões'],['R$','Financeiro'],['▤','Relatórios'],['⚙','Configurações']];
const viewSlug:Record<string,string>={'Visão geral':'inicio','Pessoas':'pessoas','Famílias e termos':'familias','Aplicativo do membro':'aplicativo','Área Kids':'kids','Igrejas e unidades':'igrejas','Usuários e permissões':'usuarios','Cultos e eventos':'eventos','Células':'celulas','Escalas':'escalas','Louvor':'louvor','Comunicação':'comunicacao','Transmissões':'transmissoes','Financeiro':'financeiro','Relatórios':'relatorios','Configurações':'configuracoes'};
const viewFromUrl=()=>{const slug=new URLSearchParams(location.search).get('pagina');return Object.keys(viewSlug).find(label=>viewSlug[label]===slug)||'Visão geral'};
const seed:Person[]=[
 {name:'Ana Carolina Souza',initials:'AS',email:'ana.souza@email.com',phone:'(11) 99824-4501',status:'Membro',group:'Célula Esperança',since:'12 fev 2021'},
 {name:'Bruno Ferreira Lima',initials:'BL',email:'bruno.lima@email.com',phone:'(11) 98763-2098',status:'Membro',group:'Louvor',since:'08 jun 2022'},
 {name:'Camila Rodrigues',initials:'CR',email:'camila.rodrigues@email.com',phone:'(11) 97751-8802',status:'Em integração',group:'Integração',since:'19 ago 2026'},
 {name:'Daniel Martins',initials:'DM',email:'daniel.m@email.com',phone:'(11) 96684-1120',status:'Visitante',group:'Sem grupo',since:'23 ago 2026'},
 {name:'Elaine dos Santos',initials:'ES',email:'elaine.santos@email.com',phone:'(11) 99127-3364',status:'Membro',group:'Intercessão',since:'15 mar 2019'},
];
const events=[['30','AGO','Culto de Celebração','Domingo · 18:00','Escala 92%'],['03','SET','Encontro de Líderes','Quinta · 20:00','42 confirmados'],['06','SET','Conferência Viver','Domingo · 09:00','187 inscrições']];

export default function DashboardApp(){
 const [active,setActive]=useState(()=>typeof window==='undefined'?'Visão geral':viewFromUrl()); const [people,setPeople]=useState<Person[]>([]); const [modal,setModal]=useState(false); const [selected,setSelected]=useState<Person|null>(null); const [editing,setEditing]=useState<Person|null>(null);
 const[sessionInfo,setSessionInfo]=useState({name:'',role:''});
 useEffect(()=>{const tenant=new URLSearchParams(location.search).get('tenant');fetch('/api/session'+(tenant?'?tenant='+encodeURIComponent(tenant):'')).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error);setSessionInfo({name:d.user.name,role:d.user.role});if(d.church)setChurch({name:d.church.name,app:d.church.app_name||d.church.name,primary:d.church.primary_color,accent:d.church.accent_color||'#d9b960'})}).catch(()=>{})},[]);
 const [church,setChurch]=useState({name:'Igreja Central',app:'Central Conecta',primary:'#285c45',accent:'#d8b769'});
 const [units,setUnits]=useState<ChurchUnit[]>([]);const [unitId,setUnitId]=useState('unit-headquarters');const [canPastoral,setCanPastoral]=useState(false);const [peopleNotice,setPeopleNotice]=useState('');
 useEffect(()=>{fetch('/api/people').then(r=>r.ok?r.json():Promise.reject()).then((saved:Person[])=>setPeople(saved)).catch(()=>{})},[]);
 useEffect(()=>{fetch('/api/units').then(r=>r.ok?r.json():Promise.reject()).then(d=>{setUnits(d.units||[]);setCanPastoral(['owner','pastor'].includes(d.currentUser?.role));if(d.units?.length&&!d.units.some((u:ChurchUnit)=>u.id===unitId))setUnitId(d.units[0].id)}).catch(()=>{})},[]);
 useEffect(()=>{const sync=()=>setActive(viewFromUrl());addEventListener('popstate',sync);return()=>removeEventListener('popstate',sync)},[]);
 const navigate=(label:string)=>{setActive(label);const url=new URL(location.href);url.searchParams.set('pagina',viewSlug[label]||'inicio');history.pushState({},'',url);};
 async function savePerson(person:Person){const response=await fetch('/api/people',{method:person.id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(person)});const result=await response.json() as {id?:string;error?:string};if(!response.ok)throw new Error(result.error||'Não foi possível salvar.');setModal(false);setEditing(null);setSelected(null);navigate('Pessoas');try{const refreshed=await fetch('/api/people');if(!refreshed.ok)throw new Error('refresh');const saved=await refreshed.json() as Person[];setPeople(saved);setSelected(saved.find(p=>p.id===(person.id||result.id))||null);setPeopleNotice('Cadastro salvo com sucesso.')}catch{setPeopleNotice('Cadastro salvo, mas a lista não foi atualizada. Recarregue a página; não repita o cadastro.')}}
 return <main className="shell" style={{'--tenant':church.primary,'--accent':church.accent} as React.CSSProperties}>
<aside className="side"><div className="brand"><i>V</i><div><b>Vinha</b><small>Gestão que frutifica</small></div></div><p className="eyebrow">GESTÃO</p><nav>{nav.map(([icon,label])=><button key={label} onClick={()=>navigate(label)} className={`${active===label?'active':''} ${label==='Cultos e eventos'?'nav-event':''}`}><span>{icon}</span>{label}</button>)}</nav><a href="/suporte" className="help"><i>?</i><div><b>Precisa de ajuda?</b><small>Abrir central de atendimento</small></div></a><div className="user"><i>MA</i><div><b>{sessionInfo.name||'Minha conta'}</b><small>{sessionInfo.role==='admin'?'Administração':sessionInfo.role}</small></div><span>⌄</span></div></aside>
<section className="main"><Header church={church.name} units={units} unitId={unitId} setUnitId={setUnitId} onCreate={()=>{setEditing(null);setModal(true)}}/><PilotModuleBoundary view={viewSlug[active] || 'unknown'}>{active==='Pessoas'?<People people={people} onAdd={()=>{setEditing(null);setModal(true)}} onSelect={setSelected}/>:active==='Famílias e termos'?<FamilyTermManager church={church.name} people={people}/>:active==='Aplicativo do membro'?<><MemberAppPlatform church={church}/><MemberNotifications people={people}/></>:active==='Área Kids'?<><KidsArea people={people}/><KidsTools people={people}/><PrinterSettings/></>:active==='Igrejas e unidades'?<Units initialUnits={units} onChange={next=>{setUnits(next);if(!next.some(u=>u.id===unitId)&&next[0])setUnitId(next[0].id)}}/>:active==='Usuários e permissões'?<Permissions people={people}/>:active==='Cultos e eventos'?<EventOperations units={units} selectedUnitId={unitId}/>:active==='Células'?<CellOperations/>:active==='Escalas'?<ScaleOperations/>:active==='Louvor'?<WorshipOperations/>:active==='Comunicação'?<CommunicationHub/>:active==='Transmissões'?<BroadcastCenter/>:active==='Financeiro'?<FinanceProviders/>:active==='Relatórios'?<AccountingCenter/>:active==='Configurações'?<ConfigurationCenter church={church} setChurch={setChurch}/>:<OrganizationOverview name={sessionInfo.name} people={people.length} units={units.length} onPeople={()=>navigate('Pessoas')} onUnits={()=>navigate('Igrejas e unidades')} onEvents={()=>navigate('Cultos e eventos')}/>}</PilotModuleBoundary></section>
  {peopleNotice&&<div role="status" className="access-flow-notice">{peopleNotice}</div>}{modal&&<PersonModal units={units} unitId={unitId} canPastoral={canPastoral} initial={editing} close={()=>{setModal(false);setEditing(null)}} save={savePerson}/>} {selected&&<PersonProfile person={selected} close={()=>setSelected(null)} edit={()=>{setEditing(selected);setSelected(null);setModal(true)}}/>}
 </main>
}

function Header({church,units,unitId,setUnitId,onCreate}:{church:string;units:ChurchUnit[];unitId:string;setUnitId:(id:string)=>void;onCreate:()=>void}){const selected=units.find(u=>u.id===unitId);return <header><label className="tenant unit-switcher"><i>{(selected?.name||church).split(' ').map(x=>x[0]).join('').slice(0,2)}</i><div><small>Visualizando</small><select value={unitId} onChange={e=>setUnitId(e.target.value)} aria-label="Selecionar unidade">{units.length?units.map(u=><option key={u.id} value={u.id}>{u.type==='headquarters'?'Sede':u.type==='congregation'?'Congregação':u.type==='regional'?'Regional':u.type==='affiliate'?'Afiliada':'Campus'} · {u.name}</option>):<option>{church}</option>}</select></div><span>⌄</span></label><div className="actions"><label>⌕ <input placeholder="Buscar pessoas, eventos..."/></label><button className="bell">♢<i>3</i></button><button className="create" onClick={onCreate}>＋ Criar novo</button></div></header>}

function Units({initialUnits,onChange}:{initialUnits:ChurchUnit[];onChange:(units:ChurchUnit[])=>void}){const [units,setUnits]=useState(initialUnits),[modal,setModal]=useState(false),[message,setMessage]=useState(''),[canManage,setCanManage]=useState(false);const load=()=>fetch('/api/units').then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error);setUnits(d.units||[]);setCanManage(Boolean(d.canManage));onChange(d.units||[])}).catch(e=>setMessage(e.message));useEffect(()=>{load()},[]);async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);const body={name:d.get('name'),type:d.get('type'),parentUnitId:d.get('parentUnitId'),pastorName:d.get('pastorName'),legalName:d.get('legalName'),taxId:d.get('taxId'),email:d.get('email'),phone:d.get('phone'),city:d.get('city'),state:d.get('state'),financialAutonomy:d.get('financialAutonomy')==='on',communicationAutonomy:d.get('communicationAutonomy')==='on',brandingAutonomy:d.get('brandingAutonomy')==='on'};const r=await fetch('/api/units',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),result=await r.json();if(!r.ok){setMessage(result.error||'Não foi possível cadastrar.');return}setModal(false);setMessage('Unidade cadastrada e registrada na auditoria.');load()}const children=(id:string)=>units.filter(u=>u.parent_unit_id===id);const roots=units.filter(u=>!u.parent_unit_id);return <div className="content units-page"><div className="page-head"><div><p className="section-over">MULTIGESTÃO</p><h1>Igrejas e unidades</h1><small>Administre sede, regionais, campus e congregações em uma única estrutura.</small></div>{canManage&&<button className="create" onClick={()=>setModal(true)}>＋ Nova unidade</button>}</div>{message&&<div className="success-note">{message}</div>}<section className="unit-summary"><article><small>Unidades ativas</small><b>{units.length}</b><span>Em toda a organização</span></article><article><small>Campus</small><b>{units.filter(u=>u.type==='campus').length}</b><span>Gestão integrada</span></article><article><small>Congregações</small><b>{units.filter(u=>u.type==='congregation').length}</b><span>Autonomia configurável</span></article><article><small>Visão atual</small><b>Consolidada</b><span>Conforme seu acesso</span></article></section><section className="unit-layout"><div className="unit-tree card"><div className="unit-section-title"><div><p className="section-over">ESTRUTURA</p><h2>Organização ministerial</h2></div><span>{units.length} unidades</span></div>{roots.map(root=><div className="unit-branch" key={root.id}><UnitRow unit={root}/>{children(root.id).map(child=><div className="unit-child" key={child.id}><UnitRow unit={child}/>{children(child.id).map(grand=><div className="unit-grandchild" key={grand.id}><UnitRow unit={grand}/></div>)}</div>)}</div>)}</div><aside className="unit-policy card"><p className="section-over">REGRAS DE ACESSO</p><h2>Visibilidade por unidade</h2><div><i>✓</i><span><b>Administração central</b><small>Visualiza sede e todas as unidades.</small></span></div><div><i>✓</i><span><b>Liderança local</b><small>Acessa somente as unidades autorizadas.</small></span></div><div><i>✓</i><span><b>Dados consolidados</b><small>Relatórios respeitam hierarquia e permissão.</small></span></div><div><i>✓</i><span><b>Auditoria ativa</b><small>Alterações ficam registradas.</small></span></div></aside></section>{modal&&<div className="overlay"><form className="modal unit-modal" onSubmit={save}><div className="modal-head"><div><p className="section-over">NOVA UNIDADE</p><h2>Adicionar à organização</h2></div><button type="button" onClick={()=>setModal(false)}>×</button></div><div className="form-row"><label>Tipo<select name="type" required><option value="campus">Campus</option><option value="congregation">Congregação</option><option value="regional">Regional</option><option value="affiliate">Igreja afiliada</option></select></label><label>Unidade responsável<select name="parentUnitId" required><option value="">Selecione</option>{units.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label></div><label>Nome da unidade<input name="name" required placeholder="Ex.: Campus Zona Norte"/></label><div className="form-row"><label>Pastor ou responsável<input name="pastorName"/></label><label>CNPJ<input name="taxId" placeholder="00.000.000/0000-00"/></label></div><label>Razão social<input name="legalName"/></label><div className="form-row"><label>E-mail<input name="email" type="email"/></label><label>Telefone<input name="phone"/></label></div><div className="form-row"><label>Cidade<input name="city"/></label><label>Estado<input name="state" maxLength={2}/></label></div><div className="unit-options"><label><input type="checkbox" name="financialAutonomy"/> Financeiro próprio</label><label><input type="checkbox" name="communicationAutonomy" defaultChecked/> Comunicação própria</label><label><input type="checkbox" name="brandingAutonomy"/> Identidade própria</label></div><div className="modal-actions"><button type="button" onClick={()=>setModal(false)}>Cancelar</button><button className="create">Cadastrar unidade</button></div></form></div>}</div>}

function UnitRow({unit}:{unit:ChurchUnit}){const label=unit.type==='headquarters'?'Sede':unit.type==='congregation'?'Congregação':unit.type==='regional'?'Regional':unit.type==='affiliate'?'Afiliada':'Campus';return <article className="unit-row"><i>{unit.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><div><b>{unit.name}</b><small>{unit.registration_code?`Código ${unit.registration_code} · `:''}{[unit.city,unit.state].filter(Boolean).join(' · ')||'Localização não informada'} · {unit.pastor_name||'Liderança a definir'}</small></div><em className={`unit-type ${unit.type}`}>{label}</em><span>{unit.financial_autonomy?'Financeiro próprio':'Financeiro central'} · {unit.communication_autonomy?'Comunicação local':'Comunicação central'}</span></article>}

function Dashboard({onEvents}:{onEvents:()=>void}){return <div className="content"><div className="welcome"><div><p>SEGUNDA-FEIRA, 24 DE AGOSTO</p><h1>Olá, Marina. <span>Que bom ter você aqui.</span></h1><small>Acompanhe o que está acontecendo na sua comunidade hoje.</small></div><button>Este mês⌄</button></div><section className="metrics"><Metric color="green" icon="♙" label="Membros ativos" value="1.284" trend="↗ 4,8% este mês"/><Metric color="gold" icon="✦" label="Novos visitantes" value="48" trend="↗ 12,5% este mês"/><Metric color="grape" icon="✓" label="Voluntários escalados" value="126" trend="18 aguardando resposta"/><Metric color="coral" icon="R$" label="Contribuições" value="R$ 86,4 mil" trend="↗ 7,2% este mês"/></section><section className="grid"><article className="card chart-card"><Title over="ENVOLVIMENTO" title="Crescimento da comunidade" action="Últimos 6 meses⌄"/><div className="legend"><span>● Membros</span><span>● Visitantes</span></div><div className="chart"><div className="axis"><span>1.400</span><span>1.200</span><span>1.000</span><span>800</span><span>600</span></div><div className="plot"><div className="area"/><div className="line"/><div className="months"><span>MAR</span><span>ABR</span><span>MAI</span><span>JUN</span><span>JUL</span><span>AGO</span></div></div></div></article><article className="card"><Title over="AGENDA" title="Próximos eventos" action="Ver todos" onAction={onEvents}/><div className="event-list">{events.map(e=><div className="event" key={e[2]}><div className="date"><b>{e[0]}</b><small>{e[1]}</small></div><div><b>{e[2]}</b><small>{e[3]}</small></div><em>{e[4]}</em></div>)}</div><button className="wide" onClick={onEvents}>＋ Abrir eventos</button></article><article className="card"><Title over="PRÓXIMO CULTO" title="Escala de domingo" action="EM MONTAGEM" badge/><div className="progress-copy"><span>23 de 25 posições confirmadas</span><b>92%</b></div><div className="progress"><i/></div><div className="team"><div><i>LF</i><i>RA</i><i>CS</i><i>＋9</i></div><small>Louvor, recepção, mídia e mais 5 ministérios</small></div><div className="warning"><i>!</i><div><b>2 posições precisam de atenção</b><small>Teclado e câmera 2 ainda estão vagas</small></div><button>Resolver</button></div></article><article className="card live"><div className="cover"><b>● AO VIVO EM 6 DIAS</b><i>▶</i></div><div className="live-copy"><p>TRANSMISSÃO</p><h2>Culto de Celebração</h2><small>Agendado no YouTube · Dom, 18:00</small><div><button>Gerenciar transmissão</button><button>•••</button></div></div></article></section></div>}

type ManagedEvent={id:string;title:string;public_slug:string;description:string;category:string;format:string;starts_at:number;ends_at:number;status:string;scope:string;unit_name?:string;registrations:number;revenue_cents:number;tickets:{id:string;name:string;price_cents:number;quantity?:number}[]};
function Events({units,selectedUnitId}:{units:ChurchUnit[];selectedUnitId:string}){const [items,setItems]=useState<ManagedEvent[]>([]),[modal,setModal]=useState(false),[message,setMessage]=useState(''),[canCreate,setCanCreate]=useState(false),[canPublish,setCanPublish]=useState(false);const load=()=>fetch('/api/events').then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error);setItems(d.events||[]);setCanCreate(Boolean(d.canCreate));setCanPublish(Boolean(d.canPublish))}).catch(e=>setMessage(e.message));useEffect(()=>{load()},[]);async function create(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget),price=Math.round(Number(d.get('price')||0)*100);const body={title:d.get('title'),description:d.get('description'),category:d.get('category'),unitId:d.get('unitId'),scope:d.get('scope'),format:d.get('format'),locationName:d.get('locationName'),address:d.get('address'),onlineUrl:d.get('onlineUrl'),startsAt:d.get('startsAt'),endsAt:d.get('endsAt'),capacity:Number(d.get('capacity')||0)||null,publish:d.get('publish')==='on',tickets:[{name:String(d.get('ticketName')||'Inscrição'),priceCents:price,quantity:Number(d.get('ticketQuantity')||0)||null}]};const r=await fetch('/api/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),result=await r.json();if(!r.ok){setMessage(result.error);return}setModal(false);setMessage(`Evento criado. Link: ${location.origin}${result.publicUrl}`);load()}async function change(id:string,action:string){const r=await fetch('/api/events',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action})}),d=await r.json();setMessage(r.ok?'Evento atualizado com sucesso.':d.error);if(r.ok)load()}const upcoming=items.filter(i=>i.status!=='cancelled'),published=items.filter(i=>i.status==='published').length,registrations=items.reduce((n,i)=>n+Number(i.registrations||0),0);return <div className="content events-page"><div className="page-head"><div><p className="section-over">PROGRAMAÇÃO</p><h1>Cultos e eventos</h1><small>Crie, publique e acompanhe inscrições por unidade ou em toda a organização.</small></div>{canCreate&&<button className="create" onClick={()=>setModal(true)}>＋ Novo evento</button>}</div>{message&&<div className="success-note event-note">{message}</div>}<section className="event-summary"><article><small>Eventos ativos</small><b>{upcoming.length}</b><span>Programação atual</span></article><article><small>Publicados</small><b>{published}</b><span>Com link público</span></article><article><small>Inscrições</small><b>{registrations}</b><span>Total recebido</span></article><article><small>Receita confirmada</small><b>{(items.reduce((n,i)=>n+Number(i.revenue_cents||0),0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</b><span>Pagamentos conciliados</span></article></section><section className="event-admin-list">{items.length?items.map(item=><article key={item.id}><div className="event-date-block"><b>{new Date(item.starts_at).toLocaleDateString('pt-BR',{day:'2-digit'})}</b><small>{new Date(item.starts_at).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</small></div><div className="event-admin-copy"><span><em>{item.category}</em><i className={item.status}>{item.status==='published'?'Publicado':item.status==='draft'?'Rascunho':'Cancelado'}</i></span><h2>{item.title}</h2><p>{item.unit_name||'Toda a organização'} · {new Date(item.starts_at).toLocaleString('pt-BR',{dateStyle:'medium',timeStyle:'short'})}</p><small>{item.tickets?.map(t=>`${t.name}: ${t.price_cents? (t.price_cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'Gratuito'}`).join(' · ')}</small></div><div className="event-admin-stats"><b>{item.registrations||0}</b><small>inscrições</small></div><div className="event-admin-actions">{item.status==='published'?<><a href={`/eventos/${item.public_slug}`} target="_blank">Abrir link</a><button onClick={()=>navigator.clipboard?.writeText(`${location.origin}/eventos/${item.public_slug}`)}>Copiar</button></>:canPublish&&<button className="publish" onClick={()=>change(item.id,'publish')}>Publicar</button>}<button onClick={()=>change(item.id,'cancel')}>•••</button></div></article>):<div className="event-empty"><i>◈</i><h2>Nenhum evento cadastrado</h2><p>Crie o primeiro evento e gere um link público de inscrição.</p></div>}</section>{modal&&<div className="overlay"><form className="modal event-modal" onSubmit={create}><div className="modal-head"><div><p className="section-over">NOVO EVENTO</p><h2>Criar programação</h2></div><button type="button" onClick={()=>setModal(false)}>×</button></div><label>Nome do evento<input name="title" required placeholder="Ex.: Conferência Vinha 2026"/></label><label>Descrição<textarea name="description" required placeholder="Apresente a programação e as informações importantes."/></label><div className="form-row"><label>Categoria<select name="category"><option>Culto</option><option>Conferência</option><option>Encontro</option><option>Retiro</option><option>Kids</option><option>Jovens</option><option>Geral</option></select></label><label>Unidade<select name="unitId" defaultValue={selectedUnitId} required>{units.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label></div><div className="form-row"><label>Início<input type="datetime-local" name="startsAt" required/></label><label>Término<input type="datetime-local" name="endsAt" required/></label></div><div className="form-row"><label>Formato<select name="format"><option value="presential">Presencial</option><option value="online">Online</option><option value="hybrid">Híbrido</option></select></label><label>Publicação<select name="scope"><option value="unit">Somente esta unidade</option><option value="organization">Toda a organização</option></select></label></div><div className="form-row"><label>Nome do local<input name="locationName"/></label><label>Capacidade total<input name="capacity" type="number" min="1"/></label></div><label>Endereço<input name="address"/></label><label>Link online ou transmissão<input name="onlineUrl" type="url"/></label><h3>Ingresso inicial</h3><div className="form-row three"><label>Nome<input name="ticketName" defaultValue="Inscrição geral"/></label><label>Valor (R$)<input name="price" type="number" min="0" step="0.01" defaultValue="0"/></label><label>Quantidade<input name="ticketQuantity" type="number" min="1"/></label></div><label className="event-publish-check"><input type="checkbox" name="publish" disabled={!canPublish}/> Publicar imediatamente e liberar o link</label><div className="modal-actions"><button type="button" onClick={()=>setModal(false)}>Cancelar</button><button className="create">Criar evento</button></div></form></div>}</div>}

function People({people,onAdd,onSelect}:{people:Person[],onAdd:()=>void,onSelect:(p:Person)=>void}){
 const [q,setQ]=useState(''),[status,setStatus]=useState('Todos'),[group,setGroup]=useState('Todos'),[showFilters,setShowFilters]=useState(false),[page,setPage]=useState(1);const pageSize=10;
 const tenant=typeof window==='undefined'?'':new URLSearchParams(location.search).get('tenant')||'';
 const groups=useMemo(()=>Array.from(new Set(people.map(p=>p.group).filter(Boolean))).sort(),[people]);
 const filtered=useMemo(()=>people.filter(p=>(p.name.toLowerCase().includes(q.toLowerCase())||p.email.toLowerCase().includes(q.toLowerCase())||p.phone.includes(q))&&(status==='Todos'||p.status===status)&&(group==='Todos'||p.group===group)),[q,status,group,people]);
 const pages=Math.max(1,Math.ceil(filtered.length/pageSize)),safePage=Math.min(page,pages),visible=filtered.slice((safePage-1)*pageSize,safePage*pageSize);useEffect(()=>setPage(1),[q,status,group]);
 return <div className="content people-page"><div className="page-head"><div><p className="section-over">COMUNIDADE</p><h1>Pessoas</h1><small>Cuide de cada pessoa e acompanhe sua jornada na igreja.</small></div><div><a className="secondary people-import" href={`/onboarding/importar-membros${tenant?`?tenant=${encodeURIComponent(tenant)}`:''}`}>⇧ Importar planilha</a><button className="create" onClick={onAdd}>＋ Nova pessoa</button></div></div><section className="people-stats"><div><i>♙</i><span><small>Total de pessoas</small><b>{people.length}</b></span></div><div><i>✦</i><span><small>Em integração</small><b>{people.filter(p=>p.status==='Em integração').length}</b></span></div><div><i>♡</i><span><small>Visitantes</small><b>{people.filter(p=>p.status==='Visitante').length}</b></span></div><div><i>⌁</i><span><small>Grupos representados</small><b>{groups.length}</b></span></div></section><section className="table-card"><div className="table-tools"><label>⌕ <input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar por nome, e-mail ou telefone"/></label><div><select aria-label="Filtrar por status" value={status} onChange={e=>setStatus(e.target.value)}><option>Todos</option><option>Membro</option><option>Em integração</option><option>Visitante</option></select><button className={showFilters?'active-filter':''} onClick={()=>setShowFilters(value=>!value)}>Mais filtros</button></div></div>{showFilters&&<div className="people-extra-filters"><label>Grupo ou ministério<select value={group} onChange={e=>setGroup(e.target.value)}><option>Todos</option>{groups.map(item=><option key={item}>{item}</option>)}</select></label><button onClick={()=>{setQ('');setStatus('Todos');setGroup('Todos')}}>Limpar filtros</button></div>}<div className="people-table"><div className="tr th"><span>PESSOA</span><span>CONTATO</span><span>STATUS</span><span>GRUPO / MINISTÉRIO</span><span>DESDE</span><span/></div>{visible.map(p=><button type="button" className="tr person-row" key={p.id||p.email} onClick={()=>onSelect(p)}><span className="person-name"><i>{p.initials}</i><span><b>{p.name}</b><small>{p.email}</small></span></span><span>{p.phone}</span><span><em className={'pill '+p.status.toLowerCase().replace(' ','-')}>{p.status}</em></span><span>{p.group}</span><span>{p.since}</span><span>›</span></button>)}{!visible.length&&<div className="people-empty">Nenhuma pessoa encontrada com os filtros selecionados.</div>}</div><footer><span>Mostrando {visible.length} de {filtered.length} pessoas</span><div><button disabled={safePage===1} onClick={()=>setPage(value=>Math.max(1,value-1))}>‹</button>{Array.from({length:pages},(_,index)=>index+1).slice(Math.max(0,safePage-2),Math.max(3,safePage+1)).map(number=><button key={number} className={safePage===number?'current':''} onClick={()=>setPage(number)}>{number}</button>)}<button disabled={safePage===pages} onClick={()=>setPage(value=>Math.min(pages,value+1))}>›</button></div></footer></section></div>
}

function Branding({church,setChurch}:{church:{name:string;app:string;primary:string;accent:string},setChurch:(c:{name:string;app:string;primary:string;accent:string})=>void}){return <div className="content settings-page"><div className="page-head"><div><p className="section-over">WHITE-LABEL</p><h1>Identidade da igreja</h1><small>Personalize como sua comunidade verá a plataforma e o aplicativo.</small></div><button className="create">Salvar alterações</button></div><div className="settings-grid"><section className="settings-form card"><h2>Marca e aplicativo</h2><p>Essas informações serão usadas no painel, site e aplicativo publicado nas lojas.</p><div className="logo-upload"><div>{church.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><span><b>Logo principal</b><small>PNG ou JPG, fundo transparente</small><button>Alterar logo</button></span></div><label>Nome da igreja<input value={church.name} onChange={e=>setChurch({...church,name:e.target.value})}/></label><label>Nome do aplicativo<input value={church.app} onChange={e=>setChurch({...church,app:e.target.value})}/><small>Aparecerá na Play Store e App Store.</small></label><div className="color-fields"><label>Cor principal<span><input type="color" value={church.primary} onChange={e=>setChurch({...church,primary:e.target.value})}/><input value={church.primary} onChange={e=>setChurch({...church,primary:e.target.value})}/></span></label><label>Cor de destaque<span><input type="color" value={church.accent} onChange={e=>setChurch({...church,accent:e.target.value})}/><input value={church.accent} onChange={e=>setChurch({...church,accent:e.target.value})}/></span></label></div><label>Vídeo de abertura<div className="video-upload"><b>▶</b><span><strong>Adicionar vídeo de abertura</strong><small>MP4 vertical · até 4 segundos · 15 MB</small></span><button>Enviar vídeo</button></div></label></section><section className="preview-panel"><p>PRÉVIA DO APLICATIVO</p><div className="phone"><div className="phone-top"/><div className="app-preview"><div className="app-brand"><i>{church.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><b>{church.app}</b></div><div className="hero-preview"><small>DOMINGO · 18H</small><h3>Culto de<br/>Celebração</h3><button>Assistir ao vivo</button></div><div className="quick"><span>♡<small>Contribuir</small></span><span>◈<small>Eventos</small></span><span>✓<small>Escalas</small></span></div><h4>Próximos eventos</h4><div className="mini-event"><i>30<small>AGO</small></i><span><b>Encontro de Famílias</b><small>Domingo · 09:00</small></span></div></div></div><small>A prévia é atualizada em tempo real. A publicação nas lojas ocorre após sua aprovação.</small></section></div></div>}

function PersonProfile({person,close,edit}:{person:Person,close:()=>void,edit:()=>void}){return <div className="overlay profile-overlay" onMouseDown={e=>e.target===e.currentTarget&&close()}><aside className="person-profile"><div className="profile-head"><button onClick={close}>×</button><i>{person.initials}</i><h2>{person.name}</h2><p>{person.status} · {person.group}</p><button className="create" onClick={edit}>Editar cadastro</button></div><div className="profile-body"><section><h3>Contato</h3><div className="profile-grid"><span><small>E-mail</small><b>{person.email||'Não informado'}</b></span><span><small>Telefone</small><b>{person.phone||'Não informado'}</b></span></div></section><section><h3>Dados pessoais</h3><div className="profile-grid"><span><small>Nascimento</small><b>{person.birthDate||'Não informado'}</b></span><span><small>CPF</small><b>{person.cpf||'Não informado'}</b></span><span><small>Estado civil</small><b>{person.maritalStatus||'Não informado'}</b></span><span><small>Unidade</small><b>{person.campus||'Não informado'}</b></span></div></section><section><h3>Vida na igreja</h3><div className="profile-grid"><span><small>Jornada</small><b>{person.status}</b></span><span><small>Batizado</small><b>{person.baptized||'Não informado'}</b></span><span><small>Grupo / ministério</small><b>{person.group}</b></span><span><small>Desde</small><b>{person.since}</b></span></div>{person.tags&&<p className="profile-tags">{person.tags.split(',').map(tag=><em key={tag}>{tag.trim()}</em>)}</p>}</section><section><h3>Endereço e segurança</h3><p>{[person.address,person.number,person.district,person.city,person.state].filter(Boolean).join(', ')||'Endereço não informado'}</p><p><b>Emergência:</b> {person.emergencyName||'Não informado'} {person.emergencyPhone&&`· ${person.emergencyPhone}`}</p></section>{person.notes&&<section className="pastoral"><h3>🔒 Observação pastoral</h3><p>{person.notes}</p></section>}</div></aside></div>}

function PersonModal({initial,close,save,units,unitId,canPastoral}:{initial:Person|null,close:()=>void,save:(p:Person)=>Promise<void>,units:ChurchUnit[],unitId:string,canPastoral:boolean}){
 const [step,setStep]=useState(1); const [saving,setSaving]=useState(false); const [error,setError]=useState(''); const [draft,setDraft]=useState<Record<string,unknown>>(()=>({...initial,notes:'',campus:initial?.campusId||initial?.campus||unitId})); const formRef=useRef<HTMLFormElement>(null);const [changedConsents,setChangedConsents]=useState<string[]>([]);
 useEffect(()=>{if(!formRef.current)return;Object.entries(draft).forEach(([key,value])=>{const field=formRef.current?.elements.namedItem(key);if(field instanceof HTMLInputElement&&field.type==='checkbox')field.checked=Boolean(value);else if(field&&'value' in field)(field as HTMLInputElement).value=String(value??'')})},[step,units]);
 function collect(){const data=new FormData(formRef.current!);const next={...draft};data.forEach((value,key)=>next[key]=String(value));['privacy','imageConsent','messages'].forEach(key=>{const field=formRef.current?.elements.namedItem(key) as HTMLInputElement|null;if(field)next[key]=field.checked});setDraft(next);return next}
 function goToStep(next:number){collect();if(next>step&&!formRef.current?.reportValidity())return;setError('');setStep(next)}
 function advance(){goToStep(step+1)}
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const all=collect();if(String(all.name||'').trim().length<2){setError('Informe o nome completo.');return}if(!units.some(u=>u.id===all.campus)){setError('Selecione uma unidade autorizada.');return}setSaving(true);setError('');try{await save(memberFormPayload(all,initial,changedConsents) as unknown as Person)}catch(error){setError(error instanceof Error?error.message:'Não foi possível salvar agora.');setSaving(false)}}
 return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&close()}><form ref={formRef} className="modal member-modal" onSubmit={submit}>
  <div className="modal-head"><div><p className="section-over">{initial?'EDITAR CADASTRO':'CADASTRO COMPLETO'}</p><h2>{initial?'Editar pessoa':'Adicionar à comunidade'}</h2></div><button type="button" onClick={close}>×</button></div>
  <div className="stepper">{['Dados pessoais','Família e endereço','Vida na igreja','Privacidade'].map((s,i)=><button type="button" key={s} className={step===i+1?'on':step>i+1?'done':''} onClick={()=>goToStep(i+1)}><i>{step>i+1?'✓':i+1}</i><span>{s}</span></button>)}</div>
  <div className="step-content">
   {step===1&&<><h3>Dados pessoais</h3><div className="photo-field"><i>＋</i><span><b>Foto de perfil</b><small>JPG ou PNG · até 5 MB</small></span><button type="button" disabled>Foto em preparação</button></div><label>Nome completo<input name="name" required placeholder="Ex.: João da Silva"/></label><div className="form-row"><label>Data de nascimento<input name="birthDate" type="date"/></label><label>Sexo<select name="gender"><option value="">Selecione</option><option>Feminino</option><option>Masculino</option><option>Prefiro não informar</option></select></label></div><div className="form-row"><label>Estado civil<select name="maritalStatus"><option>Solteiro(a)</option><option>Casado(a)</option><option>Divorciado(a)</option><option>Viúvo(a)</option></select></label><label>CPF<input name="cpf" placeholder="000.000.000-00"/></label></div><div className="form-row"><label>E-mail<input type="email" name="email" required placeholder="joao@email.com"/></label><label>Telefone<input name="phone" required placeholder="(11) 99999-9999"/></label></div></>}
   {step===2&&<><h3>Família e endereço</h3><p>Vínculos familiares serão disponibilizados em um próximo bloco.</p><div className="form-row"><label>CEP<input name="zip" placeholder="00000-000"/></label><label>Estado<input name="state" placeholder="SP"/></label></div><label>Endereço<input name="address" placeholder="Rua, avenida..."/></label><div className="form-row three"><label>Número<input name="number"/></label><label>Complemento<input name="extra"/></label><label>Bairro<input name="district"/></label></div><label>Cidade<input name="city"/></label><h3>Contato de emergência</h3><div className="form-row"><label>Nome<input name="emergencyName"/></label><label>Telefone<input name="emergencyPhone"/></label></div></>}
   {step===3&&<><h3>Jornada e vida na igreja</h3><div className="form-row"><label>Etapa da jornada<select name="status"><option>Membro</option><option>Em integração</option><option>Frequentador</option><option>Visitante</option><option>Afastado</option><option>Transferido</option></select></label><label>Unidade<select name="campus" required><option value="">Selecione a unidade</option>{units.map(u=><option value={u.id} key={u.id}>{u.name}</option>)}</select></label></div><div className="form-row"><label>Data da primeira visita<input type="date" name="firstVisit"/></label><label>Data de entrada<input type="date" name="joined"/></label></div><div className="form-row"><label>Batizado?<select name="baptized"><option>Não informado</option><option>Sim</option><option>Não</option></select></label><label>Data do batismo<input type="date" name="baptismDate"/></label></div><label>Grupo / ministério (texto livre)<input name="group" placeholder="Sem grupo"/></label><label>Tags<input name="tags" placeholder="Ex.: músico, líder, novo convertido"/></label>{canPastoral&&<label>Novo registro pastoral<textarea name="notes" placeholder="Acrescenta uma nota; o histórico anterior é preservado."/></label>}</>}
   {step===4&&<><h3>Consentimentos e acesso</h3><p>Registro administrativo: não substitui o aceite do titular no aplicativo. Na edição, apenas alterações explícitas nestas opções geram registros.</p><div className="privacy-card" onChange={event=>{const field=event.target;if(field instanceof HTMLInputElement)setChangedConsents(current=>current.includes(field.name)?current:[...current,field.name])}}><label><input type="checkbox" name="privacy"/><span><b>Tratamento de dados pessoais</b><small>Registrar o estado informado para tratamento de dados.</small></span></label><label><input type="checkbox" name="imageConsent"/><span><b>Uso de imagem</b><small>Permite uso de fotos e vídeos em comunicações da igreja.</small></span></label><label><input type="checkbox" name="messages"/><span><b>Comunicações</b><small>Autoriza receber e-mails, mensagens e notificações.</small></span></label></div><p>Salvar o cadastro não cria conta nem envia convite ao aplicativo. Campos personalizados ainda estão em preparação.</p><div className="review-box"><i>✓</i><div><b>Cadastro pronto para revisão</b><small>Você poderá editar todas as informações depois.</small></div></div></>}
  </div>
  {error&&<p className="form-error">{error}</p>}<div className="modal-actions"><button type="button" onClick={step===1?close:()=>goToStep(step-1)}>{step===1?'Cancelar':'Voltar'}</button>{step<4?<button type="button" className="create" onClick={advance}>Continuar</button>:<button className="create" disabled={saving||!units.length}>{saving?'Salvando...':initial?'Salvar alterações':'Concluir cadastro'}</button>}</div>
 </form></div>
}

function FamiliesAndTerms({church}:{church:string}){const documents=[['privacy','Tratamento de dados pessoais','LGPD, cadastro, cuidado pastoral e atividades'],['image','Uso de imagem e voz','Fotos, vídeos, transmissões e comunicações'],['messages','Comunicações','Aplicativo, e-mail, SMS e mensageria'],['minors','Responsável por menor — Área Kids','Cadastro, segurança, saúde, check-in e checkout']];return <div className="content terms-page"><div className="page-head"><div><p className="section-over">PESSOAS E PRIVACIDADE</p><h1>Famílias e termos</h1><small>Gerencie vínculos familiares e documentos de consentimento da comunidade.</small></div><button className="create">＋ Nova família</button></div><section className="family-summary"><article><i>⌂</i><div><small>Famílias cadastradas</small><b>642</b><span>1.128 pessoas vinculadas</span></div></article><article><i>♙</i><div><small>Responsáveis legais</small><b>486</b><span>Autorizações verificadas</span></div></article><article><i>✓</i><div><small>Termos vigentes</small><b>4</b><span>Versão 1.0</span></div></article></section><div className="terms-layout"><section className="terms-card"><div className="terms-title"><div><p className="section-over">DOCUMENTOS VIGENTES</p><h2>Modelos de consentimento</h2></div><span>Personalizados com a marca da igreja</span></div>{documents.map(([type,title,desc])=><article className="term-row" key={type}><i>PDF</i><div><b>{title}</b><small>{desc}</small><em>Versão 1.0 · vigente desde 25 ago 2026</em></div><a href={`/api/documents/pdf?type=${type}&church=${encodeURIComponent(church)}`} download>Baixar modelo</a></article>)}</section><aside className="brand-doc"><div className="doc-sheet"><header><i>{church.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><b>{church}</b></header><span/><h3>Termo de consentimento</h3><p>Documento personalizado com a identidade visual da igreja.</p><div/><div/><div/><footer>Vinha · Documento verificável</footer></div><h3>Padrão para todos os PDFs</h3><p>Termos e relatórios usarão automaticamente logo, nome, cores da igreja, data, versão e código do documento.</p></aside></div></div>}

type TermRecord={id:string;consent_type:string;title:string;version:string;content:string};
function FamilyTermManager({church,people}:{church:string,people:Person[]}){
 const [terms,setTerms]=useState<TermRecord[]>([]);const [pastor,setPastor]=useState('Pastor titular');const [pastorCpf,setPastorCpf]=useState('');const [editingTerm,setEditingTerm]=useState<TermRecord|null>(null);const [childOpen,setChildOpen]=useState(false);const [message,setMessage]=useState('');
 const load=()=>fetch('/api/terms').then(r=>r.json()).then(data=>{setTerms(data.terms||[]);setPastor(data.church?.senior_pastor_name||'Pastor titular');setPastorCpf(data.church?.senior_pastor_cpf||'')}).catch(()=>{});useEffect(load,[]);
 async function savePastor(){await fetch('/api/terms',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({pastorName:pastor,pastorCpf})});setMessage('Pastor titular atualizado.');}
 async function saveTerm(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);await fetch('/api/terms',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:editingTerm?.consent_type,title:d.get('title'),content:d.get('content')})});setEditingTerm(null);setMessage('Nova versão do termo publicada.');load()}
 async function saveChild(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);const guardianIds=d.getAll('guardianIds').map(String);const response=await fetch('/api/children',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fullName:d.get('fullName'),birthDate:d.get('birthDate'),allergies:d.get('allergies'),medicalNotes:d.get('medicalNotes'),guardianIds,primaryGuardianId:guardianIds[0],createdVia:'admin'})});if(response.ok){setChildOpen(false);setMessage('Criança vinculada aos responsáveis. Ela aparecerá no aplicativo deles.')}else setMessage('Selecione ao menos um responsável cadastrado.')}
 const labels:Record<string,string>={privacy:'Dados pessoais',image:'Uso de imagem e voz',messages:'Comunicações',minors:'Responsável por menor — Área Kids'};
 return <div className="content terms-page"><div className="page-head"><div><p className="section-over">PESSOAS E PRIVACIDADE</p><h1>Famílias, crianças e termos</h1><small>Documentos personalizados, responsáveis e vínculos que também aparecerão no aplicativo.</small></div><button className="create" onClick={()=>setChildOpen(true)}>＋ Cadastrar criança</button></div>{message&&<div className="success-note">✓ {message}</div>}<section className="pastor-config"><div><i>{church.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><span><small>REPRESENTANTE FIXO DOS DOCUMENTOS</small><b>Pastor titular da igreja local</b></span></div><label>Nome do pastor<input value={pastor} onChange={e=>setPastor(e.target.value)}/></label><label>CPF do pastor<input value={pastorCpf} onChange={e=>setPastorCpf(e.target.value)} placeholder="000.000.000-00"/></label><button onClick={savePastor}>Salvar representante</button></section><section className="family-summary"><article><i>⌂</i><div><small>Famílias cadastradas</small><b>642</b><span>Responsáveis e dependentes</span></div></article><article><i>♙</i><div><small>Crianças vinculadas</small><b>0</b><span>Visíveis no aplicativo dos responsáveis</span></div></article><article><i>✓</i><div><small>Termos vigentes</small><b>{terms.length||4}</b><span>Com histórico de versões</span></div></article></section><div className="terms-layout"><section className="terms-card"><div className="terms-title"><div><p className="section-over">DOCUMENTOS VIGENTES</p><h2>Termos personalizáveis</h2></div><span>Preenchidos com os dados do cadastro</span></div>{terms.map(term=><article className="term-row" key={term.id}><i>PDF</i><div><b>{labels[term.consent_type]||term.title}</b><small>{term.title}</small><em>Versão {term.version} · histórico preservado</em></div><button onClick={()=>setEditingTerm(term)}>Personalizar</button><a href={`/api/documents/pdf?type=${term.consent_type}`} download>Baixar modelo</a></article>)}</section><aside className="brand-doc"><div className="doc-sheet"><header><i>{church.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><b>{church}</b></header><span/><h3>Documento preenchido</h3><p>Membro, criança, responsáveis vinculados e pastor titular.</p><div/><div/><div/><footer>Versão e aceite verificáveis</footer></div><h3>Registro seguro</h3><p>O aceite no aplicativo guardará a versão exata, responsável, criança, data, origem e evidências técnicas.</p></aside></div>{editingTerm&&<div className="overlay"><form className="term-editor" onSubmit={saveTerm}><div className="modal-head"><div><p className="section-over">NOVA VERSÃO</p><h2>Personalizar termo</h2></div><button type="button" onClick={()=>setEditingTerm(null)}>×</button></div><label>Título<input name="title" defaultValue={editingTerm.title} required/></label><label>Texto do termo<textarea name="content" defaultValue={editingTerm.content} required/></label><div className="editor-help">Os dados do membro, responsáveis, criança e pastor são inseridos automaticamente no PDF. O texto salvo criará uma nova versão sem apagar aceites anteriores.</div><div className="modal-actions"><button type="button" onClick={()=>setEditingTerm(null)}>Cancelar</button><button className="create">Publicar nova versão</button></div></form></div>}{childOpen&&<div className="overlay"><form className="term-editor" onSubmit={saveChild}><div className="modal-head"><div><p className="section-over">ÁREA KIDS</p><h2>Cadastrar criança</h2></div><button type="button" onClick={()=>setChildOpen(false)}>×</button></div><label>Nome completo<input name="fullName" required/></label><label>Data de nascimento<input type="date" name="birthDate" required/></label><label>Alergias<input name="allergies" placeholder="Informe ou escreva: nenhuma conhecida"/></label><label>Informações médicas essenciais<textarea name="medicalNotes"/></label><fieldset><legend>Responsáveis vinculados</legend>{people.filter(p=>p.id).map(p=><label className="guardian-option" key={p.id}><input type="checkbox" name="guardianIds" value={p.id}/><span><b>{p.name}</b><small>{p.phone}</small></span></label>)}</fieldset><div className="editor-help">O primeiro responsável selecionado será o principal. Todos os vinculados poderão visualizar a criança no aplicativo conforme suas permissões.</div><div className="modal-actions"><button type="button" onClick={()=>setChildOpen(false)}>Cancelar</button><button className="create">Salvar e vincular</button></div></form></div>}</div>
}

type ChildRecord={id:string;full_name:string;birth_date:string;allergies?:string;guardians?:string;consent_granted?:number;consent_id?:string};
function MemberApp({church,people}:{church:{name:string;app:string;primary:string;accent:string},people:Person[]}){
 const members=people.filter(p=>p.id);const [guardianId,setGuardianId]=useState(members[0]?.id||'');const [children,setChildren]=useState<ChildRecord[]>([]);const [screen,setScreen]=useState<'home'|'new'|'term'>('home');const [selectedChild,setSelectedChild]=useState<ChildRecord|null>(null);const [notice,setNotice]=useState('');
 const guardian=members.find(p=>p.id===guardianId);const load=()=>guardianId&&fetch(`/api/children?guardianId=${guardianId}`).then(r=>r.json()).then(setChildren).catch(()=>setChildren([]));useEffect(()=>{load()},[guardianId]);
 async function createChild(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);const response=await fetch('/api/children',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fullName:d.get('fullName'),birthDate:d.get('birthDate'),allergies:d.get('allergies'),medicalNotes:d.get('medicalNotes'),guardianIds:[guardianId],primaryGuardianId:guardianId,createdVia:'app'})});if(response.ok){setNotice('Cadastro criado e vinculado ao seu perfil.');setScreen('home');load()}}
 async function accept(){if(!selectedChild)return;const response=await fetch('/api/consents/accept',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'minors',childId:selectedChild.id,acceptedByPersonId:guardianId,granted:true})});if(response.ok){setNotice('Termo aceito e registrado com segurança.');setScreen('home');load()}}
 async function revoke(child:ChildRecord){await fetch('/api/consents/accept',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({consentId:child.consent_id,acceptedByPersonId:guardianId})});setNotice('Consentimento revogado. A equipe Kids será avisada.');load()}
 return <div className="content member-app-page"><div className="page-head"><div><p className="section-over">PRÉVIA FUNCIONAL</p><h1>Aplicativo do responsável</h1><small>Experiência que será publicada no aplicativo personalizado da igreja.</small></div><label className="member-switch">Visualizar como<select value={guardianId} onChange={e=>setGuardianId(e.target.value)}><option value="">Selecione um membro cadastrado</option>{members.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label></div><div className="app-workspace"><aside><h3>Fluxo implementado</h3><ol><li>Responsável acessa “Meus filhos”.</li><li>Cadastra a criança pelo aplicativo.</li><li>Vincula outros responsáveis.</li><li>Lê e aceita o termo Kids.</li><li>Baixa o PDF preenchido.</li><li>Pode revogar o consentimento.</li></ol><div className="security-callout">O responsável só acessa crianças vinculadas ao próprio cadastro.</div></aside><div className="app-device"><div className="device-top"/><div className="mobile-header"><i>{church.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><span><small>{church.app}</small><b>{guardian?.name||'Responsável'}</b></span><em>♢</em></div>{notice&&<div className="mobile-notice">✓ {notice}</div>}{!guardianId?<div className="empty-mobile"><i>♙</i><h3>Selecione um membro</h3><p>Use um cadastro salvo para visualizar a experiência do responsável.</p></div>:screen==='new'?<form className="mobile-form" onSubmit={createChild}><button type="button" onClick={()=>setScreen('home')}>‹ Voltar</button><h2>Cadastrar filho(a)</h2><label>Nome completo<input name="fullName" required/></label><label>Data de nascimento<input type="date" name="birthDate" required/></label><label>Alergias<input name="allergies" placeholder="Nenhuma conhecida"/></label><label>Informações médicas<textarea name="medicalNotes"/></label><button className="mobile-primary">Salvar e vincular</button></form>:screen==='term'&&selectedChild?<div className="mobile-term"><button onClick={()=>setScreen('home')}>‹ Voltar</button><p>CONSENTIMENTO · VERSÃO VIGENTE</p><h2>Termo da Área Kids</h2><div className="term-person"><i>{selectedChild.full_name.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><span><b>{selectedChild.full_name}</b><small>Responsável: {guardian?.name}</small></span></div><article>Declaro ser responsável autorizado e consinto com o cadastro da criança, tratamento dos dados necessários à segurança, informações essenciais de saúde, check-in e checkout.</article><label className="mobile-check"><input type="checkbox" required form="accept-form"/> Li e concordo com o termo vigente.</label><form id="accept-form" onSubmit={e=>{e.preventDefault();accept()}}><button className="mobile-primary">Aceitar e registrar</button></form></div>:<div className="mobile-home"><div className="mobile-title"><div><p>MINHA FAMÍLIA</p><h2>Meus filhos</h2></div><button onClick={()=>setScreen('new')}>＋ Adicionar</button></div>{children.length?children.map(child=><article className="child-card" key={child.id}><div className="child-main"><i>{child.full_name.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><span><b>{child.full_name}</b><small>Nascimento: {child.birth_date}</small><small>{child.guardians}</small></span></div><div className={child.consent_granted?'consent-ok':'consent-pending'}>{child.consent_granted?'✓ Termo aceito':'! Termo pendente'}</div><div className="child-actions">{child.consent_granted?<><a href={`/api/documents/pdf?type=minors&personId=${guardianId}&childId=${child.id}`} download>Baixar PDF</a><button onClick={()=>revoke(child)}>Revogar</button></>:<button onClick={()=>{setSelectedChild(child);setScreen('term')}}>Ler e aceitar termo</button>}</div></article>):<div className="empty-mobile"><i>♡</i><h3>Nenhuma criança vinculada</h3><p>Cadastre seu filho para que ele apareça aqui e possa utilizar a Área Kids.</p><button onClick={()=>setScreen('new')}>Cadastrar agora</button></div>}</div>}<nav className="mobile-nav"><span>⌂<small>Início</small></span><span className="on">♙<small>Família</small></span><span>◈<small>Eventos</small></span><span>☰<small>Mais</small></span></nav></div></div></div>
}

type KidsRoom={id:string;name:string;capacity:number;location:string;color:string;session_id?:string;occupied?:number;event_name?:string};type KidsChild={id:string;full_name:string;birth_date:string;guardians?:string;consent_granted?:number;allergies?:string};type KidsCheckin={id:string;child_name:string;room_name:string;guardian_name:string;checkin_guardian_id:string;security_code:string;status:string;checked_in_at:number};
function KidsArea({people}:{people:Person[]}){const [data,setData]=useState<{rooms:KidsRoom[];children:KidsChild[];checkins:KidsCheckin[]}>({rooms:[],children:[],checkins:[]});const [room,setRoom]=useState<KidsRoom|null>(null);const [message,setMessage]=useState('');const load=()=>fetch('/api/kids').then(r=>r.json()).then(setData).catch(()=>{});useEffect(load,[]);async function action(body:Record<string,string>){const response=await fetch('/api/kids',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok){setMessage(result.error||'Não foi possível concluir.');return null}load();return result}async function openSession(r:KidsRoom){await action({action:'open-session',roomId:r.id,eventName:'Culto de Celebração'});setMessage(`Sala ${r.name} aberta para check-in.`)}async function checkin(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);const result=await action({action:'checkin',sessionId:String(room?.session_id),childId:String(d.get('childId')),guardianId:String(d.get('guardianId'))});if(result){setMessage(`Check-in concluído. Código de retirada: ${result.securityCode}`);window.open(result.labelUrl,'_blank','noopener,noreferrer');setRoom(null)}}async function checkout(item:KidsCheckin){const code=window.prompt('Informe o código de segurança entregue no check-in:');if(!code)return;const guardianId=window.prompt('Informe o ID do responsável autorizado que está retirando:');if(!guardianId)return;const result=await action({action:'checkout',checkinId:item.id,guardianId,securityCode:code});if(result)setMessage(`Checkout de ${item.child_name} concluído com segurança.`)}const active=data.checkins.filter(c=>c.status==='checked_in');return <div className="content kids-page"><div className="page-head"><div><p className="section-over">SEGURANÇA E ACOLHIMENTO</p><h1>Área Kids</h1><small>Salas, capacidade, check-in e retirada segura das crianças.</small></div><button className="create">＋ Nova sala</button></div>{message&&<div className="kids-message">{message}</div>}<section className="kids-metrics"><article><small>Crianças presentes</small><b>{active.length}</b><span>Agora</span></article><article><small>Salas abertas</small><b>{data.rooms.filter(r=>r.session_id).length}</b><span>Hoje</span></article><article><small>Termos pendentes</small><b>{data.children.filter(c=>!c.consent_granted).length}</b><span>Precisam de aceite</span></article><article><small>Ocupação total</small><b>{data.rooms.reduce((n,r)=>n+Number(r.occupied||0),0)}/{data.rooms.reduce((n,r)=>n+Number(r.capacity),0)}</b><span>Vagas utilizadas</span></article></section><div className="kids-grid"><section className="room-board"><div className="board-head"><div><p className="section-over">SALAS DE HOJE</p><h2>Culto de Celebração</h2></div><span>Atualização em tempo real</span></div>{data.rooms.map(r=><article className="room-card" key={r.id} style={{'--room':r.color} as React.CSSProperties}><i/><div><b>{r.name}</b><small>{r.location} · capacidade {r.capacity}</small><div className="room-progress"><span style={{width:`${Math.min(100,Number(r.occupied||0)/r.capacity*100)}%`}}/></div><em>{r.occupied||0} crianças · {r.capacity-Number(r.occupied||0)} vagas</em></div>{r.session_id?<button onClick={()=>setRoom(r)}>Fazer check-in</button>:<button onClick={()=>openSession(r)}>Abrir sala</button>}</article>)}</section><section className="presence-board"><div className="board-head"><div><p className="section-over">PRESENÇA</p><h2>Crianças na Área Kids</h2></div></div>{active.length?active.map(item=><article className="presence-row" key={item.id}><i>{item.child_name.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><div><b>{item.child_name}</b><small>{item.room_name} · entrada com {item.guardian_name}</small></div><em>Presente</em><button onClick={()=>checkout(item)}>Checkout</button></article>):<div className="kids-empty">Nenhum check-in ativo.</div>}</section></div>{room&&<div className="overlay"><form className="kids-checkin" onSubmit={checkin}><div className="modal-head"><div><p className="section-over">CHECK-IN SEGURO</p><h2>{room.name}</h2></div><button type="button" onClick={()=>setRoom(null)}>×</button></div><label>Criança<select name="childId" required><option value="">Selecione</option>{data.children.map(c=><option value={c.id} key={c.id} disabled={!c.consent_granted}>{c.full_name}{!c.consent_granted?' · termo pendente':''}</option>)}</select></label><label>Responsável presente<select name="guardianId" required><option value="">Selecione</option>{people.filter(p=>p.id).map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label><div className="checkin-warning">O sistema validará vínculo, autorização de retirada, termo Kids vigente e capacidade da sala.</div><div className="modal-actions"><button type="button" onClick={()=>setRoom(null)}>Cancelar</button><button className="create">Confirmar check-in</button></div></form></div>}</div>}

function KidsTools({people}:{people:Person[]}){const [rooms,setRooms]=useState<KidsRoom[]>([]);const [checkins,setCheckins]=useState<KidsCheckin[]>([]);const [mode,setMode]=useState<'room'|'volunteer'|'incident'|'call'|null>(null);const [note,setNote]=useState('');const load=()=>fetch('/api/kids').then(r=>r.json()).then(d=>{setRooms(d.rooms||[]);setCheckins((d.checkins||[]).filter((x:KidsCheckin)=>x.status==='checked_in'))}).catch(()=>{});useEffect(load,[]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const d=new FormData(e.currentTarget);const body=Object.fromEntries(d.entries()) as Record<string,string>;body.action=String(mode==='room'?'save-room':mode==='volunteer'?'add-volunteer':mode==='incident'?'incident':'call-guardian');const r=await fetch('/api/kids',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await r.json();setNote(r.ok?'Operação registrada com sucesso.':result.error||'Não foi possível concluir.');if(r.ok){setMode(null);load()}}return <div className="content kids-tools"><div className="tools-head"><div><p className="section-over">GESTÃO COMPLEMENTAR</p><h2>Salas, equipe e cuidado</h2></div></div>{note&&<div className="kids-message">{note}</div>}<section className="tool-cards"><button onClick={()=>setMode('room')}><i>＋</i><b>Criar ou editar sala</b><small>Faixa etária, capacidade, local e cor</small></button><button onClick={()=>setMode('volunteer')}><i>♙</i><b>Vincular voluntário</b><small>Equipe responsável por cada sala aberta</small></button><button onClick={()=>setMode('incident')}><i>!</i><b>Registrar ocorrência</b><small>Saúde, comportamento ou observação</small></button><button onClick={()=>setMode('call')}><i>♢</i><b>Chamar responsável</b><small>Alerta privado enviado ao aplicativo</small></button></section>{mode&&<div className="overlay"><form className="kids-checkin kids-tool-modal" onSubmit={submit}><div className="modal-head"><div><p className="section-over">ÁREA KIDS</p><h2>{mode==='room'?'Nova sala':mode==='volunteer'?'Vincular voluntário':mode==='incident'?'Registrar ocorrência':'Chamar responsável'}</h2></div><button type="button" onClick={()=>setMode(null)}>×</button></div>{mode==='room'?<><label>Nome da sala<input name="name" required/></label><div className="tool-row"><label>Idade mínima (meses)<input type="number" name="minAgeMonths" min="0" required/></label><label>Idade máxima (meses)<input type="number" name="maxAgeMonths" min="1" required/></label></div><div className="tool-row"><label>Capacidade<input type="number" name="capacity" min="1" required/></label><label>Local<input name="location" required/></label></div><label>Cor de identificação<input type="color" name="color" defaultValue="#4d8066"/></label></>:mode==='volunteer'?<><label>Sala aberta<select name="sessionId" required><option value="">Selecione</option>{rooms.filter(r=>r.session_id).map(r=><option value={r.session_id} key={r.id}>{r.name}</option>)}</select></label><label>Voluntário<select name="personId" required><option value="">Selecione</option>{people.filter(p=>p.id).map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label><label>Função<select name="role"><option>Líder da sala</option><option>Professor(a)</option><option>Auxiliar</option><option>Recepção Kids</option></select></label></>:mode==='incident'?<><label>Criança presente<select name="checkinId" required><option value="">Selecione</option>{checkins.map(c=><option value={c.id} key={c.id}>{c.child_name} · {c.room_name}</option>)}</select></label><label>Categoria<select name="category"><option>Observação</option><option>Saúde</option><option>Comportamento</option><option>Acidente</option><option>Segurança</option></select></label><label>Descrição<textarea name="description" required/></label><label>Gravidade<select name="severity"><option value="low">Baixa</option><option value="medium">Média</option><option value="high">Alta</option></select></label><label className="guardian-option"><input type="checkbox" name="guardianNotified" value="1"/> Responsável já foi comunicado</label></>:<><label>Criança presente<select name="checkinId" required><option value="">Selecione</option>{checkins.map(c=><option value={c.id} key={c.id}>{c.child_name} · {c.room_name}</option>)}</select></label><label>Mensagem ao responsável<textarea name="reason" defaultValue="A equipe Kids solicita sua presença na recepção." required/></label><div className="checkin-warning">O aviso será privado e ficará registrado no histórico.</div></>}<div className="modal-actions"><button type="button" onClick={()=>setMode(null)}>Cancelar</button><button className="create">Salvar</button></div></form></div>}</div>}

type GuardianNotice={id:string;reason:string;status:string;sent_at:number;acknowledged_at?:number;child_name:string;room_name:string};
function MemberNotifications({people}:{people:Person[]}){const members=people.filter(p=>p.id),[guardianId,setGuardianId]=useState(members[0]?.id||''),[items,setItems]=useState<GuardianNotice[]>([]);const load=()=>guardianId&&fetch(`/api/app/notifications?guardianId=${guardianId}`).then(r=>r.json()).then(setItems).catch(()=>{});useEffect(load,[guardianId]);async function acknowledge(id:string){await fetch('/api/app/notifications',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,guardianId})});load()}return <div className="content notice-center"><div className="notice-head"><div><p className="section-over">NOTIFICAÇÕES DO APLICATIVO</p><h2>Chamados da Área Kids</h2><small>O responsável confirma o recebimento e a equipe acompanha o atendimento.</small></div><select value={guardianId} onChange={e=>setGuardianId(e.target.value)}><option value="">Selecione o responsável</option>{members.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></div><section>{items.length?items.map(n=><article key={n.id} className={n.status==='sent'?'unread':''}><i>!</i><div><b>{n.child_name} · {n.room_name}</b><p>{n.reason}</p><small>{n.status==='sent'?'Aguardando confirmação':'Recebido pelo responsável'}</small></div>{n.status==='sent'?<button onClick={()=>acknowledge(n.id)}>Confirmar recebimento</button>:<em>✓ Confirmado</em>}</article>):<div className="notice-empty">Nenhum chamado para este responsável.</div>}</section></div>}

function PrinterSettings(){const [saved,setSaved]=useState(false);return <div className="content printer-settings"><div><i>▦</i><span><p className="section-over">IMPRESSÃO KIDS</p><h2>Configuração da etiqueta térmica</h2><small>A etiqueta abre automaticamente após o check-in.</small></span></div><label>Tamanho<select><option>62 × 40 mm</option><option>80 × 50 mm</option></select></label><label>Impressora<select><option>Impressora padrão do dispositivo</option><option>Zebra / ZPL via diálogo</option><option>Brother / sistema</option></select></label><label><input type="checkbox" defaultChecked/> Abrir impressão após check-in</label><button onClick={()=>setSaved(true)}>{saved?'✓ Configuração salva':'Salvar configuração'}</button></div>}

type UnitAccess={unit_id:string;role:string;include_children:number;unit_name?:string;unit_type?:string};
type AccessUser={id:string;name:string;email:string;role:string;status:string;person_id?:string;unit_access?:UnitAccess[]};
function Permissions({people}:{people:Person[]}){
 const [users,setUsers]=useState<AccessUser[]>([]),[current,setCurrent]=useState<AccessUser|null>(null),[units,setUnits]=useState<ChurchUnit[]>([]),[accessUser,setAccessUser]=useState<AccessUser|null>(null),[error,setError]=useState(''),[saved,setSaved]=useState('');
 const load=()=>Promise.all([fetch('/api/users'),fetch('/api/units')]).then(async([ur,xr])=>{const u=await ur.json(),x=await xr.json();if(!ur.ok)throw new Error(u.error);setUsers(u.users);setCurrent(u.current);if(xr.ok)setUnits(x.units||[])}).catch(e=>setError(e.message));
 useEffect(()=>{load()},[]);
 async function update(user:AccessUser,role:string,personId:string){const r=await fetch('/api/users',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:user.id,role,status:user.status,personId})});const d=await r.json();if(!r.ok){setSaved(d.error);return}setSaved('Permissão atualizada e registrada na auditoria.');load()}
 const roles=[['admin','Administrador'],['pastor','Pastor'],['secretary','Secretaria'],['kids_leader','Líder Kids'],['kids_volunteer','Voluntário Kids'],['responsible','Responsável'],['member','Membro']];
 return <div className="content permissions-page"><div className="page-head"><div><p className="section-over">SEGURANÇA E ACESSO</p><h1>Usuários e permissões</h1><small>Cada pessoa visualiza somente os módulos e unidades autorizados.</small></div><span className="current-access">Seu acesso: <b>{roles.find(r=>r[0]===current?.role)?.[1]||current?.role||'Carregando'}</b></span></div>{error?<div className="access-denied"><i>🔒</i><h2>Acesso restrito</h2><p>{error}</p></div>:<><section className="permission-summary"><article><small>Usuários ativos</small><b>{users.filter(u=>u.status==='active').length}</b></article><article><small>Administradores</small><b>{users.filter(u=>u.role==='admin').length}</b></article><article><small>Acessos locais</small><b>{users.reduce((n,u)=>n+(u.unit_access?.length||0),0)}</b></article><article><small>Auditoria</small><b>Ativa</b></article></section>{saved&&<div className="success-note">{saved}</div>}<section className="access-table unit-access-table"><div className="access-row head"><span>USUÁRIO</span><span>PERFIL</span><span>UNIDADES</span><span>STATUS</span></div>{users.map(u=><div className="access-row" key={u.id}><span className="access-person"><i>{u.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><span><b>{u.name}</b><small>{u.email}</small></span></span><select value={u.role} disabled={current?.role!=='admin'} onChange={e=>update(u,e.target.value,u.person_id||'')}>{roles.map(r=><option key={r[0]} value={r[0]}>{r[1]}</option>)}</select><div className="unit-access-cell"><span>{['admin','pastor'].includes(u.role)?'Todas as unidades':u.unit_access?.length?`${u.unit_access.length} unidade(s)`:'Nenhuma unidade'}</span>{current?.role==='admin'&&!['admin','pastor'].includes(u.role)&&<button onClick={()=>setAccessUser(u)}>Configurar</button>}</div><em className={u.status}>{u.status==='active'?'Ativo':'Inativo'}</em></div>)}</section><section className="role-guide"><h2>O que cada perfil pode fazer</h2><div>{roles.map(([key,label])=><article key={key}><b>{label}</b><small>{key==='admin'?'Acesso completo a todas as unidades':key==='pastor'?'Visão geral ministerial e pastoral':key==='secretary'?'Cadastros e rotinas nas unidades liberadas':key==='kids_leader'?'Gestão Kids nas unidades liberadas':key==='kids_volunteer'?'Check-in nas unidades liberadas':key==='responsible'?'Filhos, termos e chamados':'Perfil, agenda e atividades'}</small></article>)}</div></section></>}{accessUser&&<UnitAccessModal user={accessUser} units={units} close={()=>setAccessUser(null)} saved={message=>{setSaved(message);setAccessUser(null);load()}}/>}</div>
}

function UnitAccessModal({user,units,close,saved}:{user:AccessUser;units:ChurchUnit[];close:()=>void;saved:(message:string)=>void}){const initial=new Map((user.unit_access||[]).map(a=>[a.unit_id,a]));const [entries,setEntries]=useState<Record<string,{enabled:boolean;role:string;includeChildren:boolean}>>(()=>Object.fromEntries(units.map(unit=>{const found=initial.get(unit.id);return[unit.id,{enabled:Boolean(found),role:found?.role||'viewer',includeChildren:Boolean(found?.include_children)}]}))),[error,setError]=useState('');const roles=[['unit_admin','Administrador local'],['pastor','Pastor local'],['secretary','Secretaria'],['events_manager','Gestor de eventos'],['communication','Comunicação'],['finance','Financeiro'],['viewer','Somente leitura']];const toggle=(id:string,next:Partial<{enabled:boolean;role:string;includeChildren:boolean}>)=>setEntries(current=>({...current,[id]:{...current[id],...next}}));async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const selected=units.filter(u=>entries[u.id]?.enabled).map(u=>({unitId:u.id,role:entries[u.id].role,includeChildren:entries[u.id].includeChildren}));const r=await fetch('/api/users/unit-access',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:user.id,entries:selected})}),d=await r.json();if(!r.ok){setError(d.error||'Não foi possível salvar.');return}saved('Acesso às unidades atualizado e registrado na auditoria.')}return <div className="overlay"><form className="modal unit-access-modal" onSubmit={submit}><div className="modal-head"><div><p className="section-over">ACESSO POR UNIDADE</p><h2>{user.name}</h2><small>Defina o papel e o alcance em cada unidade.</small></div><button type="button" onClick={close}>×</button></div>{error&&<div className="form-error">{error}</div>}<div className="unit-access-list">{units.map(unit=><article key={unit.id} className={entries[unit.id]?.enabled?'selected':''}><label className="unit-access-check"><input type="checkbox" checked={entries[unit.id]?.enabled||false} onChange={e=>toggle(unit.id,{enabled:e.target.checked})}/><i>{unit.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</i><span><b>{unit.name}</b><small>{unit.type==='headquarters'?'Sede':unit.type==='congregation'?'Congregação':unit.type==='regional'?'Regional':unit.type==='affiliate'?'Afiliada':'Campus'}</small></span></label><select disabled={!entries[unit.id]?.enabled} value={entries[unit.id]?.role||'viewer'} onChange={e=>toggle(unit.id,{role:e.target.value})}>{roles.map(([key,label])=><option key={key} value={key}>{label}</option>)}</select><label className="child-access"><input type="checkbox" disabled={!entries[unit.id]?.enabled} checked={entries[unit.id]?.includeChildren||false} onChange={e=>toggle(unit.id,{includeChildren:e.target.checked})}/> Incluir unidades subordinadas</label></article>)}</div><div className="access-help">Administradores e pastores gerais já possuem acesso automático a toda a organização. Estas regras são aplicadas aos demais perfis.</div><div className="modal-actions"><button type="button" onClick={close}>Cancelar</button><button className="create">Salvar acessos</button></div></form></div>}

function Metric({color,icon,label,value,trend}:{color:string,icon:string,label:string,value:string,trend:string}){return <article className="metric"><i className={color}>{icon}</i><div><small>{label}</small><b>{value}</b><span>{trend}</span></div></article>}
function Title({over,title,action,badge=false,onAction}:{over:string,title:string,action:string,badge?:boolean;onAction?:()=>void}){return <div className="title"><div><p>{over}</p><h2>{title}</h2></div><button className={badge?'badge':''} onClick={onAction}>{action}</button></div>}




